class Solution {
    public long countStableSubarrays(int[] capacity) {
        int n = capacity.length;
        long[] pre = new long[n + 1];
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + capacity[i];
        Map<Long, Map<Long, Long>> m = new HashMap<>();
        long ans = 0;
        for (int r = 2; r < n; r++) {
            int l = r - 2;
            m.computeIfAbsent(pre[l] + 2L * capacity[l], k -> new HashMap<>())
             .merge((long) capacity[l], 1L, Long::sum);
            Map<Long, Long> inner = m.get(pre[r]);
            if (inner != null) ans += inner.getOrDefault((long) capacity[r], 0L);
        }
        return ans;
    }
}

c.javascript:
var countStableSubarrays = function(capacity) {
    const n = capacity.length;
    const pre = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) pre[i + 1] = pre[i] + capacity[i];
    const m = new Map();
    let ans = 0;
    for (let r = 2; r < n; r++) {
        const l = r - 2;
        const k1 = pre[l] + 2 * capacity[l], k2 = capacity[l];
        if (!m.has(k1)) m.set(k1, new Map());
        const inner = m.get(k1);
        inner.set(k2, (inner.get(k2) || 0) + 1);
        const hit = m.get(pre[r]);
        if (hit) ans += hit.get(capacity[r]) || 0;
    }
    return ans;
};
